const isKanjiAssignment = (assignment: AssignmentPayload | null | undefined) => {
    if (!assignment) return false;
    return assignment.units.some((unit) => (
        unit.name.includes('漢字')
        || unit.id.includes('KANJI')
        || unit.modes.some((mode) => String(mode).includes('KANJI') || String(mode).includes('KANKEN'))
    ));
};

const getAssignmentAnswerModeSummary = (assignment: AssignmentPayload | null | undefined, languageMode: LanguageMode) => {
    if (languageMode === 'ENGLISH') {
        const answerModeLabel = assignment?.answerMode === 'INPUT' ? 'Input' : 'Multiple choice';
        return `${isKanjiAssignment(assignment) ? 'Kanji answer mode' : 'Answer mode'}: ${answerModeLabel}`;
    }
    const answerModeLabel = assignment?.answerMode === 'INPUT' ? '入力' : '4択';
    return `${trans(isKanjiAssignment(assignment) ? '漢字の答え方' : '答え方', languageMode)}: ${trans(answerModeLabel, languageMode)}`;
};

const getAssignmentCustomTargetCorrect = (assignment: AssignmentPayload | null | undefined) => {
    const customProblemCount = assignment?.customProblems?.length || 0;
    if (customProblemCount <= 0) return 0;
    return Math.min(customProblemCount, Math.max(1, Number(assignment?.customTargetCorrect || customProblemCount)));
};

const getAssignmentTargetSummary = (assignment: AssignmentPayload, languageMode: LanguageMode) => {
    const unitSummaries = assignment.units.map(unit => {
        const targetCorrect = unit.targetCorrect || 10;
        if (languageMode === 'ENGLISH') {
            return `${formatProblemUnitName(unit.name, languageMode)} (${targetCorrect} questions)`;
        }
        const unitName = languageMode === 'HIRAGANA' ? unit.name : trans(unit.name, languageMode);
        const questionCountLabel = languageMode === 'HIRAGANA' ? 'もん' : '問';
        return `${unitName} (${targetCorrect}${questionCountLabel})`;
    });
    const customProblemCount = assignment.customProblems?.length || 0;
    if (customProblemCount > 0) {
        const customTargetCorrect = getAssignmentCustomTargetCorrect(assignment);
        unitSummaries.push(languageMode === 'ENGLISH'
            ? `${trans('オリジナル問題', languageMode)} (${customTargetCorrect} / ${customProblemCount} correct)`
            : languageMode === 'HIRAGANA'
                ? `おりじなるもんだい (${customProblemCount}もんちゅう ${customTargetCorrect}もんせいかい)`
                : `オリジナル問題 (${customProblemCount}問中 ${customTargetCorrect}問正解)`);
    }
    return unitSummaries.join(' / ') || trans('オリジナル問題', languageMode);
};

const getAssignmentTitle = (title: string, languageMode: LanguageMode) => {
    if (languageMode !== 'ENGLISH') return trans(title, languageMode);
    const dailyTitle = title.match(/^(.+) デイリー課題 (.+)$/);
    if (dailyTitle) return `${trans(dailyTitle[1], languageMode)} Daily Assignment ${dailyTitle[2]}`;
    return trans(title, languageMode);
};

const formatAssignmentProgressUnitName = (name: string, languageMode: LanguageMode) => {
    if (languageMode !== 'ENGLISH') return name;
    const customRemaining = name.match(/^オリジナル問題 残り(\d+)問$/);
    if (customRemaining) return `${trans('オリジナル問題', languageMode)} (${customRemaining[1]} remaining)`;
    return formatProblemUnitName(name, languageMode);
};

