        selectedEnemyId: null,
        narrativeLog: [],
        combatLog: [],
        rewards: [],
        selectionState: { active: false, type: 'DISCARD', amount: 0 },
        isEndless: false,
        parryState: { active: false, enemyId: null, success: false },
        activeEffects: [],
        coopBattleState: null,
